void ADFTypes::Compatibility::read(IO::File& buffer) {
    ChildHash.read(buffer);
    ParentHash.read(buffer);
    Tags.read(buffer);
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        Operation = (bitfield_value >> 0) & ((1ULL << 2) - 1);
    }
    buffer.skip(7);
}

void ADFTypes::Compatibility::print(std::ostream &out) const {
    out << "ChildHash: ";
    ChildHash.print(out);
    out << "\n";
    out << "ParentHash: ";
    ParentHash.print(out);
    out << "\n";
    out << "Tags: \n";
    Tags.print(out);
    out << "\n";
    out << "Operation: " << Operation << "\n";
}

