void ADFTypes::Equipment::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        EquipmentName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    EquipmentHash = buffer.read_pod<uint32>();
    EquipmentNoQualityHash = buffer.read_pod<uint32>();
    DisplayNameHash = buffer.read_pod<uint32>();
    DisplayDescriptionHash = buffer.read_pod<uint32>();
    DisplayIconHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        DisplayIconString = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    DisplayCompatibilityHash = buffer.read_pod<uint32>();
    AmmoTypeHash = buffer.read_pod<uint32>();
    CashPrice = buffer.read_pod<uint32>();
    Stackable = buffer.read_pod<uint32>();
    Units = buffer.read_pod<int32>();
    SlotType.read(buffer);
    Weight = buffer.read_pod<float32>();
    EquipmentCategory = buffer.read_pod<int32>();
    LockMode = static_cast<ADFTypes::LockMode>(buffer.read_pod<uint32>());
    UnlockCondition = static_cast<ADFTypes::UnlockCondition>(buffer.read_pod<uint32>());
    UnlockTarget = buffer.read_pod<uint32>();
    EquipmentSubCatHash = buffer.read_pod<uint32>();
    for(int i = 0; i < 2; ++i) {
        throw std::runtime_error("Unsupported inline array inner type");
    }
    ReceivedAmountDLC = buffer.read_pod<uint32>();
    MagazineSize = buffer.read_pod<uint32>();
    ShortDisplayNameHash = buffer.read_pod<uint32>();
    Quality = buffer.read_pod<uint8>();
    buffer.skip(3);
    XPWhenUsed = buffer.read_pod<uint32>();
    SubCategoryHash = buffer.read_pod<uint32>();
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        SoundEvent = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        AcceptsVisionModule = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
    AugmentCapacity = buffer.read_pod<uint32>();
    UsableFromInventory = static_cast<ADFTypes::UseMethod>(buffer.read_pod<uint32>());
    buffer.skip(4);
    Crafting.read(buffer);
    ClothingGender = static_cast<ADFTypes::EquipmentGender>(buffer.read_pod<uint32>());
    ClothingCategory = buffer.read_pod<uint32>();
    BlocksClothingCategory = buffer.read_pod<int32>();
    ClothingCategoryHash = buffer.read_pod<uint32>();
    PrimaryColor = buffer.read_pod<uint32>();
    SecondaryColor = buffer.read_pod<uint32>();
    DetailColor = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        FPModelMale = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        FPModelFemale = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        TPModelMale = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        TPModelFemale = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        DecalSlots = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        AttributeFile = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

