void ADFTypes::SchematicTree::read(IO::File& buffer) {
    Name = buffer.read_pod<uint32>();
    Currency = buffer.read_pod<uint32>();
    ContentKey = buffer.read_pod<uint32>();
    buffer.skip(4);
    Nodes.read(buffer);
    RootNodes.read(buffer);
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        ShowInSchematicsScreen = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(7);
}

void ADFTypes::SchematicTree::print(std::ostream &out) const {
    out << "Name: " << Name << "\n";
    out << "Currency: " << Currency << "\n";
    out << "ContentKey: " << ContentKey << "\n";
    out << "Nodes: \n";
    Nodes.print(out);
    out << "\n";
    out << "RootNodes: \n";
    RootNodes.print(out);
    out << "\n";
    out << "ShowInSchematicsScreen: " << ShowInSchematicsScreen << "\n";
}

nlohmann::json ADFTypes::SchematicTree::to_json() const {
    nlohmann::json _res;
    _res["Name"] = Name;
    _res["Currency"] = Currency;
    _res["ContentKey"] = ContentKey;
    _res["Nodes"] = Nodes.to_json();
    _res["RootNodes"] = RootNodes.to_json();
    _res["ShowInSchematicsScreen"] = ShowInSchematicsScreen;
    return _res;
}

