void ADFTypes::CharacterConstants::read(IO::File& buffer) {
    for(int i = 0; i < 2; ++i) {
        DetailTilingFactorUV[i] = buffer.read_pod<float32>();
    }
    SpecularGloss = buffer.read_pod<float32>();
    TransmissionIntensity = buffer.read_pod<float32>();
    DiffuseRoughness = buffer.read_pod<float32>();
    EmissiveIntensity = buffer.read_pod<float32>();
    NightVisibility = buffer.read_pod<float32>();
    RimFrontStrength = buffer.read_pod<float32>();
    CameraStrength = buffer.read_pod<float32>();
    CameraSpecular = buffer.read_pod<float32>();
    RimStrength = buffer.read_pod<float32>();
    DirtFactor = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        DoubleSided = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        AlphaBlending = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        FeatureMapTint = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        WrinkleMap = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        CameraLightingEnable = (bitfield_value >> 5) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

