void ADFTypes::FoliageConstants::read(IO::File& buffer) {
    for(int i = 0; i < 4; ++i) {
        DiffuseModulator[i] = buffer.read_pod<float32>();
    }
    SpecularGloss = buffer.read_pod<float32>();
    EmissionIntensity = buffer.read_pod<float32>();
    TransmissionIntensity = buffer.read_pod<float32>();
    DiffuseWrap = buffer.read_pod<float32>();
    Reflectivity = buffer.read_pod<float32>();
    SpecularFresnel = buffer.read_pod<float32>();
    SphereNormalStrength = buffer.read_pod<float32>();
    OneOverSubpixelDetailFadeRange = buffer.read_pod<float32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        RenderTransparent = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        ObjectSpaceNormalMap = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        UseInteractionDisplacement = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        UseInteractionFlattening = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        UseCharacterInteractionFlattening = (bitfield_value >> 4) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
}

