void ADFTypes::CollectibleInfo::read(IO::File& buffer) {
    ID = buffer.read_pod<uint64>();
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Type = buffer.read_pod<int8>();
    buffer.skip(3);
    ContentKey = buffer.read_pod<uint32>();
    for(int i = 0; i < 3; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

void ADFTypes::CollectibleInfo::print(std::ostream &out) const {
    out << "ID: " << ID << "\n";
    out << "Name: " << Name << "\n";
    out << "Type: " << Type << "\n";
    out << "ContentKey: " << ContentKey << "\n";
    out << "Position: \n";
    Position.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::CollectibleInfo::to_json() const {
    nlohmann::json _res;
    _res["ID"] = ID;
    _res["Name"] = Name;
    _res["Type"] = Type;
    _res["ContentKey"] = ContentKey;
    _res["Position"] = Position.to_json();
    return _res;
}

