void ADFTypes::PlayerSettings::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        LocalPlayerExpentity = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        RemotePlayerExpentity = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    DisableCharacterCustomization = buffer.read_pod<uint8>();
    buffer.skip(3);
    DownedAbandonTime = buffer.read_pod<float32>();
    CustomGravity = buffer.read_pod<float32>();
    KnockDownForceThreshold = buffer.read_pod<float32>();
    PlayerHealthSettings.read(buffer);
    LowHealthScreenEffectSettings.read(buffer);
    PlayerMusicSettings.read(buffer);
    DamageOverTimeEffectSettings.read(buffer);
    buffer.skip(4);
    StorageSettings.read(buffer);
    SchematicCurrencySettings.read(buffer);
    buffer.skip(4);
}

void ADFTypes::PlayerSettings::print(std::ostream &out) const {
    out << "LocalPlayerExpentity: " << LocalPlayerExpentity << "\n";
    out << "RemotePlayerExpentity: " << RemotePlayerExpentity << "\n";
    out << "DisableCharacterCustomization: " << DisableCharacterCustomization << "\n";
    out << "DownedAbandonTime: " << DownedAbandonTime << "\n";
    out << "CustomGravity: " << CustomGravity << "\n";
    out << "KnockDownForceThreshold: " << KnockDownForceThreshold << "\n";
    PlayerHealthSettings.print(out);
    LowHealthScreenEffectSettings.print(out);
    PlayerMusicSettings.print(out);
    DamageOverTimeEffectSettings.print(out);
    StorageSettings.print(out);
    SchematicCurrencySettings.print(out);
}

nlohmann::json ADFTypes::PlayerSettings::to_json() const {
    nlohmann::json _res;
    _res["LocalPlayerExpentity"] = LocalPlayerExpentity;
    _res["RemotePlayerExpentity"] = RemotePlayerExpentity;
    _res["DisableCharacterCustomization"] = DisableCharacterCustomization;
    _res["DownedAbandonTime"] = DownedAbandonTime;
    _res["CustomGravity"] = CustomGravity;
    _res["KnockDownForceThreshold"] = KnockDownForceThreshold;
    _res["PlayerHealthSettings"] = PlayerHealthSettings.to_json();
    _res["LowHealthScreenEffectSettings"] = LowHealthScreenEffectSettings.to_json();
    _res["PlayerMusicSettings"] = PlayerMusicSettings.to_json();
    _res["DamageOverTimeEffectSettings"] = DamageOverTimeEffectSettings.to_json();
    _res["StorageSettings"] = StorageSettings.to_json();
    _res["SchematicCurrencySettings"] = SchematicCurrencySettings.to_json();
    return _res;
}

