    out << "VehiclePreferedCameraThirdPerson: " << VehiclePreferedCameraThirdPerson << "\n";
    out << "TrackingEnabled: " << TrackingEnabled << "\n";
    out << "ShownTrackingOptIn: " << ShownTrackingOptIn << "\n";
    out << "CrashReportingEnabled: " << CrashReportingEnabled << "\n";
    out << "ShownCrashReportingEnabledOptIn: " << ShownCrashReportingEnabledOptIn << "\n";
