void ADFTypes::Fin::read(IO::File& buffer) {
    physics_component_name.read(buffer);
    area = buffer.read_pod<float32>();
    height = buffer.read_pod<float32>();
    effective_in_air = buffer.read_pod<uint8>();
    effective_in_water = buffer.read_pod<uint8>();
    buffer.skip(2);
    steering_factor = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        hinge_position[i] = buffer.read_pod<float32>();
    }
    hinge_angles.read(buffer);
    distance_to_hinge = buffer.read_pod<float32>();
    min_angle_deg = buffer.read_pod<float32>();
    max_angle_deg = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::Fin::print(std::ostream &out) const {
    physics_component_name.print(out);
    out << "area: " << area << "\n";
    out << "height: " << height << "\n";
    out << "effective_in_air: " << effective_in_air << "\n";
    out << "effective_in_water: " << effective_in_water << "\n";
    out << "steering_factor: " << steering_factor << "\n";
    out << "hinge_position: \n";
    hinge_position.print(out);
    out << "\n";
    hinge_angles.print(out);
    out << "distance_to_hinge: " << distance_to_hinge << "\n";
    out << "min_angle_deg: " << min_angle_deg << "\n";
    out << "max_angle_deg: " << max_angle_deg << "\n";
}

nlohmann::json ADFTypes::Fin::to_json() const {
    nlohmann::json _res;
    _res["physics_component_name"] = physics_component_name.to_json();
    _res["area"] = area;
    _res["height"] = height;
    _res["effective_in_air"] = effective_in_air;
    _res["effective_in_water"] = effective_in_water;
    _res["steering_factor"] = steering_factor;
    _res["hinge_position"] = hinge_position.to_json();
    _res["hinge_angles"] = hinge_angles.to_json();
    _res["distance_to_hinge"] = distance_to_hinge;
    _res["min_angle_deg"] = min_angle_deg;
    _res["max_angle_deg"] = max_angle_deg;
    return _res;
}

