void ADFTypes::CharacterProfile18::read(IO::File& buffer) {
    CharacterLooks.read(buffer);
    for(int i = 0; i < 128; ++i) {
        Skills[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 128; ++i) {
        SkillLevel[i] = buffer.read_pod<uint8>();
    }
    for(int i = 0; i < 16; ++i) {
        SkillPointsSpent[i] = buffer.read_pod<uint32>();
    }
    SkillPoints = buffer.read_pod<uint32>();
    ActiveSkill = buffer.read_pod<uint32>();
    Xp = buffer.read_pod<uint32>();
    Level = buffer.read_pod<uint16>();
    Created = buffer.read_pod<uint8>();
    buffer.skip(1);
    Inventory.read(buffer);
    for(int i = 0; i < 18; ++i) {
        PPInventorySlot[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 18; ++i) {
        InventorySlotPreferredItem[i] = buffer.read_pod<uint32>();
    }
    VehicleData.read(buffer);
    VehiclePreferedCameraThirdPerson = buffer.read_pod<uint8>();
    buffer.skip(7);
    EmotesUnlocked.read(buffer);
    for(int i = 0; i < 8; ++i) {
        EmoteSlots[i] = buffer.read_pod<uint32>();
    }
    Collectables.read(buffer);
    DistanceTravelled = buffer.read_pod<float32>();
    TimeOfDay = buffer.read_pod<float32>();
    WeatherTime = buffer.read_pod<float32>();
    buffer.skip(4);
    PlayerPositions.read(buffer);
    LastLevelUpTS = buffer.read_pod<uint64>();
    GivenDLCItems.read(buffer);
    RaidLootAcquired.read(buffer);
    ActiveTitle = buffer.read_pod<uint32>();
    CharacterPlayTime = buffer.read_pod<uint32>();
    BadLuckProtection.read(buffer);
    Statistics.read(buffer);
    Challenges.read(buffer);
    EquipmentNotes.read(buffer);
    for(int i = 0; i < 1; ++i) {
        CompanionData[i].read(buffer);
    }
    PityCounters.read(buffer);
    FixVersion = buffer.read_pod<uint32>();
    buffer.skip(4);
}

