    out << "manual_clutch_blend_time: " << manual_clutch_blend_time << "\n";
    out << "forward_ratio_percentage: " << forward_ratio_percentage << "\n";
    out << "low_gear_forward_ratio_pct: " << low_gear_forward_ratio_pct << "\n";
