void ADFTypes::GeneralMkIIIConstants::read(IO::File& buffer) {
    NormalStrength = buffer.read_pod<float32>();
    Reflectivity_1 = buffer.read_pod<float32>();
    Roughness_1 = buffer.read_pod<float32>();
    DiffuseWrap_1 = buffer.read_pod<float32>();
    Emissive_1 = buffer.read_pod<float32>();
    Transmission_1 = buffer.read_pod<float32>();
    ClearCoat_1 = buffer.read_pod<float32>();
    Roughness_2 = buffer.read_pod<float32>();
    DiffuseWrap_2 = buffer.read_pod<float32>();
    Emissive_2 = buffer.read_pod<float32>();
    Transmission_2 = buffer.read_pod<float32>();
    Reflectivity_2 = buffer.read_pod<float32>();
    ClearCoat_2 = buffer.read_pod<float32>();
    Roughness_3 = buffer.read_pod<float32>();
    DiffuseWrap_3 = buffer.read_pod<float32>();
    Emissive_3 = buffer.read_pod<float32>();
    Transmission_3 = buffer.read_pod<float32>();
    Reflectivity_3 = buffer.read_pod<float32>();
    ClearCoat_3 = buffer.read_pod<float32>();
    Roughness_4 = buffer.read_pod<float32>();
    DiffuseWrap_4 = buffer.read_pod<float32>();
    Emissive_4 = buffer.read_pod<float32>();
    Transmission_4 = buffer.read_pod<float32>();
    Reflectivity_4 = buffer.read_pod<float32>();
    ClearCoat_4 = buffer.read_pod<float32>();
    LayeredHeightMapUVScale = buffer.read_pod<float32>();
    LayeredUVScale = buffer.read_pod<float32>();
    LayeredHeight1Influence = buffer.read_pod<float32>();
    LayeredHeight2Influence = buffer.read_pod<float32>();
    LayeredHeightMapInfluence = buffer.read_pod<float32>();
    LayeredMaskInfluence = buffer.read_pod<float32>();
    LayeredShift = buffer.read_pod<float32>();
    LayeredRoughness = buffer.read_pod<float32>();
    LayeredDiffuseWrap = buffer.read_pod<float32>();
    LayeredEmissive = buffer.read_pod<float32>();
    LayeredTransmission = buffer.read_pod<float32>();
    LayeredReflectivity = buffer.read_pod<float32>();
    LayeredClearCoat = buffer.read_pod<float32>();
    DecalBlend = buffer.read_pod<float32>();
    DecalBlendNormal = buffer.read_pod<float32>();
    DecalReflectivity = buffer.read_pod<float32>();
    DecalRoughness = buffer.read_pod<float32>();
    DecalDiffuseWrap = buffer.read_pod<float32>();
    DecalEmissive = buffer.read_pod<float32>();
    DecalTransmission = buffer.read_pod<float32>();
    DecalClearCoat = buffer.read_pod<float32>();
    OverlayHeightInfluence = buffer.read_pod<float32>();
    OverlayHeightMapInfluence = buffer.read_pod<float32>();
    OverlayMaskInfluence = buffer.read_pod<float32>();
    OverlayShift = buffer.read_pod<float32>();
    OverlayColorR = buffer.read_pod<float32>();
    OverlayColorG = buffer.read_pod<float32>();
    OverlayColorB = buffer.read_pod<float32>();
    OverlayBrightness = buffer.read_pod<float32>();
    OverlayGloss = buffer.read_pod<float32>();
    OverlayMetallic = buffer.read_pod<float32>();
    OverlayReflectivity = buffer.read_pod<float32>();
    OverlayRoughness = buffer.read_pod<float32>();
    OverlayDiffuseWrap = buffer.read_pod<float32>();
    OverlayEmissive = buffer.read_pod<float32>();
    OverlayTransmission = buffer.read_pod<float32>();
    OverlayClearCoat = buffer.read_pod<float32>();
    DamageReflectivity = buffer.read_pod<float32>();
    DamageRoughness = buffer.read_pod<float32>();
    DamageDiffuseWrap = buffer.read_pod<float32>();
    DamageEmissive = buffer.read_pod<float32>();
    DamageTransmission = buffer.read_pod<float32>();
    DamageHeightInfluence = buffer.read_pod<float32>();
    DamageMaskInfluence = buffer.read_pod<float32>();
    DamageClearCoat = buffer.read_pod<float32>();
    DepthBias = buffer.read_pod<float32>();
    HardwareDepthBias = buffer.read_pod<float32>();
    HardwareSlopeBias = buffer.read_pod<float32>();
    MinTimeOfDayEmissive = buffer.read_pod<float32>();
    StartFadeOutDistanceEmissiveSq = buffer.read_pod<float32>();
    GIEmissionModulator = buffer.read_pod<float32>();
    RippleAngle = buffer.read_pod<float32>();
    RippleSpeed = buffer.read_pod<float32>();
    RippleMagnitude = buffer.read_pod<float32>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        DynamicEmissive = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        AlphaBlend = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        BackfaceCulling = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        WorldSpaceNormals = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        UsePropertyMasking = (bitfield_value >> 5) & ((1ULL << 1) - 1);
        UseLayered = (bitfield_value >> 6) & ((1ULL << 1) - 1);
        UseOverlay = (bitfield_value >> 7) & ((1ULL << 1) - 1);
        UseDecal = (bitfield_value >> 8) & ((1ULL << 1) - 1);
        UseDamage = (bitfield_value >> 9) & ((1ULL << 1) - 1);
        UseVertexAnimation = (bitfield_value >> 10) & ((1ULL << 1) - 1);
        RoadDepthBias = (bitfield_value >> 11) & ((1ULL << 1) - 1);
        AnisotropicFiltering = (bitfield_value >> 12) & ((1ULL << 1) - 1);
        WireAA = (bitfield_value >> 13) & ((1ULL << 1) - 1);
    }
}

