void ADFTypes::WorldSaveData25::read(IO::File& buffer) {
    ReserveId = buffer.read_pod<int32>();
    buffer.skip(4);
    Statistics.read(buffer);
    DifficultyLevel = buffer.read_pod<uint32>();
    DifficultyScaleByPlayers = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 4; ++i) {
        Worlds[i].read(buffer);
    }
    ActiveWorldIndex = buffer.read_pod<uint32>();
    buffer.skip(4);
}

void ADFTypes::WorldSaveData25::print(std::ostream &out) const {
    out << "ReserveId: " << ReserveId << "\n";
    out << "Statistics: \n";
    Statistics.print(out);
    out << "\n";
    out << "DifficultyLevel: " << DifficultyLevel << "\n";
    out << "DifficultyScaleByPlayers: " << DifficultyScaleByPlayers << "\n";
    out << "Worlds: \n";
    Worlds.print(out);
    out << "\n";
    out << "ActiveWorldIndex: " << ActiveWorldIndex << "\n";
}

nlohmann::json ADFTypes::WorldSaveData25::to_json() const {
    nlohmann::json _res;
    _res["ReserveId"] = ReserveId;
    _res["Statistics"] = Statistics.to_json();
    _res["DifficultyLevel"] = DifficultyLevel;
    _res["DifficultyScaleByPlayers"] = DifficultyScaleByPlayers;
    _res["Worlds"] = Worlds.to_json();
    _res["ActiveWorldIndex"] = ActiveWorldIndex;
    return _res;
}

