void ADFTypes::StuntAreas::read(IO::File& buffer) {
    for(int i = 0; i < 32; ++i) {
        stunt_areas[i].read(buffer);
    }
    number_of_stunt_areas = buffer.read_pod<uint8>();
    buffer.skip(1);
    for(int i = 0; i < 64; ++i) {
        welding_info[i].read(buffer);
    }
    number_of_welding_info = buffer.read_pod<uint16>();
    buffer.skip(4);
}

void ADFTypes::StuntAreas::print(std::ostream &out) const {
    out << "stunt_areas: \n";
    stunt_areas.print(out);
    out << "\n";
    out << "number_of_stunt_areas: " << number_of_stunt_areas << "\n";
    out << "welding_info: \n";
    welding_info.print(out);
    out << "\n";
    out << "number_of_welding_info: " << number_of_welding_info << "\n";
}

nlohmann::json ADFTypes::StuntAreas::to_json() const {
    nlohmann::json _res;
    _res["stunt_areas"] = stunt_areas.to_json();
    _res["number_of_stunt_areas"] = number_of_stunt_areas;
    _res["welding_info"] = welding_info.to_json();
    _res["number_of_welding_info"] = number_of_welding_info;
    return _res;
}

