void ADFTypes::ProfileSaveData5::read(IO::File& buffer) {
    Collectables.read(buffer);
    EmotesUnlocked.read(buffer);
    for(int i = 0; i < 8; ++i) {
        EmoteSlots[i] = buffer.read_pod<uint32>();
    }
    TrackingId = buffer.read_pod<uint64>();
    Settings.read(buffer);
    CompletedBounties.read(buffer);
    LastLogin = buffer.read_pod<int64>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        SocialDisabled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    VehiclePreferedCameraThirdPerson = buffer.read_pod<uint8>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        TrackingEnabled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        ShownTrackingOptIn = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        CrashReportingEnabled = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        ShownCrashReportingEnabledOptIn = (bitfield_value >> 3) & ((1ULL << 1) - 1);
    }
    buffer.skip(5);
    ResourceStorage.read(buffer);
    SafehouseStorage.read(buffer);
    SafehouseStorageSizeColumns = buffer.read_pod<uint8>();
    SafehouseStorageSizeRows = buffer.read_pod<uint8>();
    buffer.skip(2);
    FixVersion = buffer.read_pod<uint32>();
}

