void ADFTypes::Part::read(IO::File& buffer) {
    name.read(buffer);
    damage_type.read(buffer);
    behavior.read(buffer);
    model.read(buffer);
    model_swap.read(buffer);
    part_index = buffer.read_pod<int8>();
    parent_part_index = buffer.read_pod<int8>();
    buffer.skip(2);
    for(int i = 0; i < 16; ++i) {
        parent_space_offset[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 16; ++i) {
        bind_pose_bone_matrix[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    children_part_indices.read(buffer);
    starts_loose = buffer.read_pod<int8>();
    should_break = buffer.read_pod<int8>();
    prevent_mesh_swap_while_alive = buffer.read_pod<int8>();
    prevent_loosening_while_alive = buffer.read_pod<int8>();
    prevent_breaking_while_alive = buffer.read_pod<int8>();
    always_mesh_swap_on_death = buffer.read_pod<int8>();
    always_loosen_on_death = buffer.read_pod<int8>();
    always_break_on_death = buffer.read_pod<int8>();
    disappears_when_broken = buffer.read_pod<int8>();
    appears_on_death = buffer.read_pod<int8>();
    disappears_on_death = buffer.read_pod<int8>();
    starts_deleted = buffer.read_pod<int8>();
    is_deformable = buffer.read_pod<int8>();
    has_lights = buffer.read_pod<int8>();
    has_world_collision_shape = buffer.read_pod<int8>();
    only_collides_once_loose = buffer.read_pod<int8>();
    only_collides_once_broken = buffer.read_pod<int8>();
    buffer.skip(7);
    hide_parts_when_broken.read(buffer);
    meshswap_parts_when_broken.read(buffer);
    loosen_parts_when_broken.read(buffer);
    break_parts_when_broken.read(buffer);
    world_collision_instance_id = buffer.read_pod<int16>();
    raycast_instance_id = buffer.read_pod<int16>();
    grandpa_world_instance_id = buffer.read_pod<int16>();
    grandpa_raycast_instance_id = buffer.read_pod<int16>();
    world_collision_body_id = buffer.read_pod<int16>();
    raycast_body_id = buffer.read_pod<int16>();
    constraint_index = buffer.read_pod<int16>();
    buffer.skip(2);
    for(int i = 0; i < 4; ++i) {
        centroid[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 4; ++i) {
        deformation_centroid_offset[i] = buffer.read_pod<float32>();
    }
}

