void ADFTypes::StuntArea::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    name_hash = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        part_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    part_hash = buffer.read_pod<uint32>();
    part_index = buffer.read_pod<uint32>();
    for(int i = 0; i < 16; ++i) {
        deform_points[i] = buffer.read_pod<uint32>();
    }
    for(int i = 0; i < 16; ++i) {
        edge_validity[i] = buffer.read_pod<uint8>();
    }
    number_of_deform_points = buffer.read_pod<uint16>();
    active = buffer.read_pod<uint16>();
    for(int i = 0; i < 48; ++i) {
        vertices3D_local[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 42; ++i) {
        triangle_indices[i] = buffer.read_pod<uint8>();
    }
    number_of_triangles = buffer.read_pod<uint16>();
    bounding_box_local.read(buffer);
    for(int i = 0; i < 3; ++i) {
        center_local[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
}

