    nlohmann::json _res;
    _res["BypassModifier"] = BypassModifier;
    _res["HintHashes"] = HintHashes.to_json();
    _res["DeltaPivotOffset"] = DeltaPivotOffset.to_json();
    _res["DeltaPitch"] = DeltaPitch;
    _res["DeltaYaw"] = DeltaYaw;
