    _res["DeltaAzimuth"] = DeltaAzimuth;
    _res["DeltaElevation"] = DeltaElevation;
    _res["DeltaDistance"] = DeltaDistance;
    _res["BlendInSpring"] = BlendInSpring.to_json();
