void ADFTypes::WeaponSwayTuning::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        ik_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        reference_joint = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    disable_rotation_sway = buffer.read_pod<uint32>();
    disable_translation_sway = buffer.read_pod<uint32>();
    spring_coeff_drag = buffer.read_pod<float32>();
    spring_coeff_catchup = buffer.read_pod<float32>();
    wp_scale_yaw = buffer.read_pod<float32>();
    wp_scale_pitch = buffer.read_pod<float32>();
    wp_scale_roll = buffer.read_pod<float32>();
    wp_max_yaw_input = buffer.read_pod<float32>();
    wp_max_pitch_input = buffer.read_pod<float32>();
    wp_max_roll_input = buffer.read_pod<float32>();
    wp_translation_scale_x = buffer.read_pod<float32>();
    wp_translation_scale_y = buffer.read_pod<float32>();
    aim_scale_yaw = buffer.read_pod<float32>();
    aim_scale_pitch = buffer.read_pod<float32>();
    aim_scale_roll = buffer.read_pod<float32>();
    aim_max_yaw_input = buffer.read_pod<float32>();
    aim_max_pitch_input = buffer.read_pod<float32>();
    aim_max_roll_input = buffer.read_pod<float32>();
    aim_translation_scale_x = buffer.read_pod<float32>();
    aim_translation_scale_y = buffer.read_pod<float32>();
    mouse_wp_scale_yaw = buffer.read_pod<float32>();
    mouse_wp_scale_pitch = buffer.read_pod<float32>();
    mouse_wp_scale_roll = buffer.read_pod<float32>();
    mouse_wp_translation_scale_x = buffer.read_pod<float32>();
    mouse_wp_translation_scale_y = buffer.read_pod<float32>();
    mouse_aim_scale_yaw = buffer.read_pod<float32>();
    mouse_aim_scale_pitch = buffer.read_pod<float32>();
    mouse_aim_scale_roll = buffer.read_pod<float32>();
    mouse_aim_translation_scale_x = buffer.read_pod<float32>();
    mouse_aim_translation_scale_y = buffer.read_pod<float32>();
    overshoot_scale = buffer.read_pod<float32>();
    buffer.skip(4);
}

