void ADFTypes::HunterMissionObjective::read(IO::File& buffer) {
    Id = buffer.read_pod<int32>();
    ForceActive = buffer.read_pod<uint8>();
    Enabled = buffer.read_pod<uint8>();
    Required = buffer.read_pod<uint8>();
    Visible = buffer.read_pod<uint8>();
    VisibleOnStart = buffer.read_pod<uint8>();
    ShowProgression = buffer.read_pod<uint8>();
    buffer.skip(2);
    Name.read(buffer);
    NameShort.read(buffer);
    TimeLimit = buffer.read_pod<int32>();
    ShowTimer = buffer.read_pod<uint8>();
    ShowExclusively = buffer.read_pod<uint8>();
    ShowInLog = buffer.read_pod<uint8>();
    buffer.skip(5);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        MarkerName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ShowMarker.read(buffer);
    HideMarker.read(buffer);
    ResetEvent.read(buffer);
    Reward.read(buffer);
    MultiplayerCompletionMode = buffer.read_pod<uint8>();
    buffer.skip(1);
    ActivateEvent.read(buffer);
    CountRequired = buffer.read_pod<int32>();
    InitialCount = buffer.read_pod<int32>();
    DependenciesRequired.read(buffer);
    DependenciesOptional.read(buffer);
    Conditions.read(buffer);
    ForceCompleteEvent.read(buffer);
    buffer.skip(2);
}

