void ADFTypes::CameraCollisionParams::read(IO::File& buffer) {
    BypassModifier = buffer.read_pod<uint8>();
    DrawDebug = buffer.read_pod<uint8>();
    buffer.skip(2);
    for(int i = 0; i < 3; ++i) {
        CollisionResponseOffset[i] = buffer.read_pod<float32>();
    }
    Radius = buffer.read_pod<float32>();
    PassthroughRadius = buffer.read_pod<float32>();
    MaxCameraPassthroughThickness = buffer.read_pod<float32>();
    CollideCharacter = buffer.read_pod<uint8>();
    buffer.skip(3);
    ExtensionMaxVelocity = buffer.read_pod<float32>();
    MaxDistancePushVelocity = buffer.read_pod<float32>();
    MovementCastAhead = buffer.read_pod<float32>();
    AngularCastAhead = buffer.read_pod<float32>();
    MinCollisionDist = buffer.read_pod<float32>();
    CameraPlaneMargin = buffer.read_pod<float32>();
    CameraPushMargin = buffer.read_pod<float32>();
    DistanceToOpacitySpline.read(buffer);
    IgnoreOffsetDistanceChange = buffer.read_pod<uint8>();
    IgnorePlayerVehicle = buffer.read_pod<uint8>();
    KeepAboveWater = buffer.read_pod<uint8>();
    DisableClosestProximityCollision = buffer.read_pod<uint8>();
    CollisionResponseUprightViewAligned = buffer.read_pod<uint8>();
    buffer.skip(3);
}

