void ADFTypes::WeaponTuning::read(IO::File& buffer) {
    bullet_weapon.read(buffer);
    buffer.skip(4);
    fire_modes.read(buffer);
    magazine_size = buffer.read_pod<int32>();
    reload_time_scale = buffer.read_pod<float32>();
    kinetic_energy = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        trigger_sensitivity[i] = buffer.read_pod<float32>();
    }
    aim_timer_override = buffer.read_pod<float32>();
    weapon_wobble_modifier = buffer.read_pod<float32>();
    weapon_recoil_penalty = buffer.read_pod<float32>();
    ZeroingIndex = buffer.read_pod<int8>();
    buffer.skip(7);
    ZeroingIndexOnRequirement.read(buffer);
    ZeroingSettings.read(buffer);
    HorizontalOffset = buffer.read_pod<float32>();
    VerticalOffset = buffer.read_pod<float32>();
    DepthOffset = buffer.read_pod<float32>();
    buffer.skip(4);
    ScopeOffsetSettings.read(buffer);
    UISettings.read(buffer);
    unlimited_ammo = buffer.read_pod<uint8>();
    adjust_aim_direction_after_trajectory = buffer.read_pod<uint8>();
    buffer.skip(6);
    alternative_hit_entity_spawning.read(buffer);
    ai_tuning.read(buffer);
    move_speed_mul_curve.read(buffer);
    move_speed_mul_abscissa.read(buffer);
    move_speed_ignore_aim_steering_params = buffer.read_pod<uint8>();
    buffer.skip(7);
}

