void ADFTypes::ShakeAnimation::read(IO::File& buffer) {
    Control.read(buffer);
    Pan = buffer.read_pod<uint8>();
    Tilt = buffer.read_pod<uint8>();
    Dutch = buffer.read_pod<uint8>();
    buffer.skip(1);
    RotationMaxAmplitude = buffer.read_pod<float32>();
    RotationAmplitudeScale = buffer.read_pod<float32>();
    RotationAmplitudeScaleSpline.read(buffer);
    RotationMaxFrequency = buffer.read_pod<float32>();
    RotationFrequencyScale = buffer.read_pod<float32>();
    RotationFrequencyScaleSpline.read(buffer);
    TranslationMaxAmplitude = buffer.read_pod<float32>();
    TranslationAmplitudeScale = buffer.read_pod<float32>();
    TranslationAmplitudeScaleSpline.read(buffer);
    TranslationMaxFrequency = buffer.read_pod<float32>();
    TranslationFrequencyScale = buffer.read_pod<float32>();
    TranslationFrequencyScaleSpline.read(buffer);
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        MasterAmplitudeScaleBBKey = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        MasterFrequencyScaleBBKey = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::ShakeAnimation::print(std::ostream &out) const {
    Control.print(out);
    out << "Pan: " << Pan << "\n";
    out << "Tilt: " << Tilt << "\n";
    out << "Dutch: " << Dutch << "\n";
    out << "RotationMaxAmplitude: " << RotationMaxAmplitude << "\n";
    out << "RotationAmplitudeScale: " << RotationAmplitudeScale << "\n";
    RotationAmplitudeScaleSpline.print(out);
    out << "RotationMaxFrequency: " << RotationMaxFrequency << "\n";
    out << "RotationFrequencyScale: " << RotationFrequencyScale << "\n";
    RotationFrequencyScaleSpline.print(out);
    out << "TranslationMaxAmplitude: " << TranslationMaxAmplitude << "\n";
    out << "TranslationAmplitudeScale: " << TranslationAmplitudeScale << "\n";
    TranslationAmplitudeScaleSpline.print(out);
    out << "TranslationMaxFrequency: " << TranslationMaxFrequency << "\n";
    out << "TranslationFrequencyScale: " << TranslationFrequencyScale << "\n";
    TranslationFrequencyScaleSpline.print(out);
    out << "MasterAmplitudeScaleBBKey: " << MasterAmplitudeScaleBBKey << "\n";
    out << "MasterFrequencyScaleBBKey: " << MasterFrequencyScaleBBKey << "\n";
}

