void ADFTypes::PartNode::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        part_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        world_collision_shape_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        raycast_shape_name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        mesh_path = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    is_deformable = buffer.read_pod<int32>();
    part_index = buffer.read_pod<int16>();
    parent_part = buffer.read_pod<int16>();
    child_parts.read(buffer);
}

void ADFTypes::PartNode::print(std::ostream &out) const {
    out << "part_name: " << part_name << "\n";
    out << "world_collision_shape_name: " << world_collision_shape_name << "\n";
    out << "raycast_shape_name: " << raycast_shape_name << "\n";
    out << "mesh_path: " << mesh_path << "\n";
    out << "is_deformable: " << is_deformable << "\n";
    out << "part_index: " << part_index << "\n";
    out << "parent_part: " << parent_part << "\n";
    out << "child_parts: \n";
    child_parts.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::PartNode::to_json() const {
    nlohmann::json _res;
    _res["part_name"] = part_name;
    _res["world_collision_shape_name"] = world_collision_shape_name;
    _res["raycast_shape_name"] = raycast_shape_name;
    _res["mesh_path"] = mesh_path;
    _res["is_deformable"] = is_deformable;
    _res["part_index"] = part_index;
    _res["parent_part"] = parent_part;
    _res["child_parts"] = child_parts.to_json();
    return _res;
}

