void ADFTypes::PfxBodyProperties::read(IO::File& buffer) {
    desired_mass = buffer.read_pod<float32>();
    desired_mass_density = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        center_of_mass_offset[i] = buffer.read_pod<float32>();
    }
    inertia_pitch_multiplier = buffer.read_pod<float32>();
    inertia_yaw_multiplier = buffer.read_pod<float32>();
    inertia_roll_multiplier = buffer.read_pod<float32>();
    max_linear_speed = buffer.read_pod<float32>();
    max_angular_speed = buffer.read_pod<float32>();
    linear_damping = buffer.read_pod<float32>();
    angular_damping = buffer.read_pod<float32>();
    gravity_factor = buffer.read_pod<float32>();
    time_factor = buffer.read_pod<float32>();
}

