    EquipmentIDCounter = buffer.read_pod<uint32>();
    buffer.skip(4);
    ItemStash.read(buffer);
    UnknownItemsStash.read(buffer);
    InaccessibleItems.read(buffer);
    GivenDLCItems.read(buffer);
    ActiveCharacterIndex = buffer.read_pod<uint32>();
    buffer.skip(4);
