void ADFTypes::PfxBreakablePartInstance::read(IO::File& buffer) {
    for(int i = 0; i < 16; ++i) {
        breakable_space_transform[i] = buffer.read_pod<float32>();
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        collision_path = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    breaking_collision_impulse = buffer.read_pod<float32>();
    buffer.skip(20);
}

void ADFTypes::PfxBreakablePartInstance::print(std::ostream &out) const {
    out << "breakable_space_transform: \n";
    breakable_space_transform.print(out);
    out << "\n";
    out << "collision_path: " << collision_path << "\n";
    out << "breaking_collision_impulse: " << breaking_collision_impulse << "\n";
}

nlohmann::json ADFTypes::PfxBreakablePartInstance::to_json() const {
    nlohmann::json _res;
    _res["breakable_space_transform"] = breakable_space_transform.to_json();
    _res["collision_path"] = collision_path;
    _res["breaking_collision_impulse"] = breaking_collision_impulse;
    return _res;
}

