    hit_entity_spawns_on_requirement.print(out);
    out << "\n";
    out << "hit_entity_spawn_method: " << hit_entity_spawn_method << "\n";
    out << "hit_entity_spawn_max_count: " << hit_entity_spawn_max_count << "\n";
    out << "hit_entity_spawn_on_kill_hit: " << hit_entity_spawn_on_kill_hit << "\n";
    out << "hit_entity_use_bullet_model: " << hit_entity_use_bullet_model << "\n";
    out << "trigger_non_attached_entities: " << trigger_non_attached_entities << "\n";
    out << "spawn_hit_entity_weapon_controller_only: " << spawn_hit_entity_weapon_controller_only << "\n";
    out << "use_arc_movement: " << use_arc_movement << "\n";
    out << "use_staggered_arming: " << use_staggered_arming << "\n";
