void ADFTypes::CameraAnimationControl::read(IO::File& buffer) {
    DrawDebug = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        StartMessage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        StopMessage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        ParameterMessage = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    AutoStart = buffer.read_pod<uint8>();
    buffer.skip(3);
    Duration = buffer.read_pod<float32>();
    EaseInTime = buffer.read_pod<float32>();
    EaseOutTime = buffer.read_pod<float32>();
    Looping = buffer.read_pod<uint8>();
    EnableHorizonStabilization = buffer.read_pod<uint8>();
    buffer.skip(6);
}

void ADFTypes::CameraAnimationControl::print(std::ostream &out) const {
    out << "DrawDebug: " << DrawDebug << "\n";
    out << "StartMessage: " << StartMessage << "\n";
    out << "StopMessage: " << StopMessage << "\n";
    out << "ParameterMessage: " << ParameterMessage << "\n";
    out << "AutoStart: " << AutoStart << "\n";
    out << "Duration: " << Duration << "\n";
    out << "EaseInTime: " << EaseInTime << "\n";
    out << "EaseOutTime: " << EaseOutTime << "\n";
    out << "Looping: " << Looping << "\n";
    out << "EnableHorizonStabilization: " << EnableHorizonStabilization << "\n";
}

nlohmann::json ADFTypes::CameraAnimationControl::to_json() const {
    nlohmann::json _res;
    _res["DrawDebug"] = DrawDebug;
    _res["StartMessage"] = StartMessage;
    _res["StopMessage"] = StopMessage;
    _res["ParameterMessage"] = ParameterMessage;
    _res["AutoStart"] = AutoStart;
    _res["Duration"] = Duration;
    _res["EaseInTime"] = EaseInTime;
    _res["EaseOutTime"] = EaseOutTime;
    _res["Looping"] = Looping;
    _res["EnableHorizonStabilization"] = EnableHorizonStabilization;
    return _res;
}

