void ADFTypes::FirstPersonCameraModifierParams::read(IO::File& buffer) {
    DrawDebug = buffer.read_pod<uint8>();
    BypassModifier = buffer.read_pod<uint8>();
    buffer.skip(2);
    InputParams.read(buffer);
    ForegroundFOV = buffer.read_pod<float32>();
    WorldFOV = buffer.read_pod<float32>();
    UseGameSettingsWorldFov = buffer.read_pod<uint8>();
    buffer.skip(7);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        ForegroundBBKey = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ForegroundPitchEnabled = buffer.read_pod<uint8>();
    buffer.skip(7);
    for(int i = 0; i < 3; ++i) {
        AimAdjustmentSegments[i] = buffer.read_cstring();
    }
    AlignToSurface = buffer.read_pod<uint8>();
    buffer.skip(3);
    AlignToSurfaceStiffness = buffer.read_pod<float32>();
    ProneAllowedHeightPushUp = buffer.read_pod<float32>();
    PronePushUpRayLength = buffer.read_pod<float32>();
    PronePushUpRayBackOffset = buffer.read_pod<float32>();
    AimAssist.read(buffer);
    buffer.skip(4);
}

void ADFTypes::FirstPersonCameraModifierParams::print(std::ostream &out) const {
    out << "DrawDebug: " << DrawDebug << "\n";
    out << "BypassModifier: " << BypassModifier << "\n";
    InputParams.print(out);
    out << "ForegroundFOV: " << ForegroundFOV << "\n";
    out << "WorldFOV: " << WorldFOV << "\n";
    out << "UseGameSettingsWorldFov: " << UseGameSettingsWorldFov << "\n";
    out << "ForegroundBBKey: " << ForegroundBBKey << "\n";
    out << "ForegroundPitchEnabled: " << ForegroundPitchEnabled << "\n";
    out << "AimAdjustmentSegments: \n";
    AimAdjustmentSegments.print(out);
    out << "\n";
    out << "AlignToSurface: " << AlignToSurface << "\n";
    out << "AlignToSurfaceStiffness: " << AlignToSurfaceStiffness << "\n";
    out << "ProneAllowedHeightPushUp: " << ProneAllowedHeightPushUp << "\n";
    out << "PronePushUpRayLength: " << PronePushUpRayLength << "\n";
    out << "PronePushUpRayBackOffset: " << PronePushUpRayBackOffset << "\n";
    AimAssist.print(out);
}

nlohmann::json ADFTypes::FirstPersonCameraModifierParams::to_json() const {
    nlohmann::json _res;
    _res["DrawDebug"] = DrawDebug;
    _res["BypassModifier"] = BypassModifier;
    _res["InputParams"] = InputParams.to_json();
    _res["ForegroundFOV"] = ForegroundFOV;
    _res["WorldFOV"] = WorldFOV;
    _res["UseGameSettingsWorldFov"] = UseGameSettingsWorldFov;
    _res["ForegroundBBKey"] = ForegroundBBKey;
    _res["ForegroundPitchEnabled"] = ForegroundPitchEnabled;
    _res["AimAdjustmentSegments"] = AimAdjustmentSegments.to_json();
    _res["AlignToSurface"] = AlignToSurface;
    _res["AlignToSurfaceStiffness"] = AlignToSurfaceStiffness;
    _res["ProneAllowedHeightPushUp"] = ProneAllowedHeightPushUp;
    _res["PronePushUpRayLength"] = PronePushUpRayLength;
    _res["PronePushUpRayBackOffset"] = PronePushUpRayBackOffset;
    _res["AimAssist"] = AimAssist.to_json();
    return _res;
}

