void ADFTypes::ActionToken::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        DebugName = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Count = buffer.read_pod<uint32>();
    AcquireWaitMin = buffer.read_pod<float32>();
    AcquireWaitMax = buffer.read_pod<float32>();
    TokenCooldownMin = buffer.read_pod<float32>();
    TokenCooldownMax = buffer.read_pod<float32>();
    buffer.skip(4);
}

void ADFTypes::ActionToken::print(std::ostream &out) const {
    out << "DebugName: " << DebugName << "\n";
    out << "Count: " << Count << "\n";
    out << "AcquireWaitMin: " << AcquireWaitMin << "\n";
    out << "AcquireWaitMax: " << AcquireWaitMax << "\n";
    out << "TokenCooldownMin: " << TokenCooldownMin << "\n";
    out << "TokenCooldownMax: " << TokenCooldownMax << "\n";
}

nlohmann::json ADFTypes::ActionToken::to_json() const {
    nlohmann::json _res;
    _res["DebugName"] = DebugName;
    _res["Count"] = Count;
    _res["AcquireWaitMin"] = AcquireWaitMin;
    _res["AcquireWaitMax"] = AcquireWaitMax;
    _res["TokenCooldownMin"] = TokenCooldownMin;
    _res["TokenCooldownMax"] = TokenCooldownMax;
    return _res;
}

