void ADFTypes::ProceduralShakeParams::read(IO::File& buffer) {
    BypassModifier = buffer.read_pod<uint8>();
    SyncPhase = buffer.read_pod<uint8>();
    buffer.skip(2);
    PitchFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        PitchAmplitude[i] = buffer.read_pod<float32>();
    }
    RollFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        RollAmplitude[i] = buffer.read_pod<float32>();
    }
    YawFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        YawAmplitude[i] = buffer.read_pod<float32>();
    }
    LocalXFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LocalXAmplitude[i] = buffer.read_pod<float32>();
    }
    LocalYFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LocalYAmplitude[i] = buffer.read_pod<float32>();
    }
    LocalZFrequency = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        LocalZAmplitude[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        SpeedRange[i] = buffer.read_pod<float32>();
    }
    SpeedMaxScale = buffer.read_pod<float32>();
}

