void ADFTypes::RagdollSetting::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    ControllerType = buffer.read_pod<uint8>();
    MapAnimationToPhysics = buffer.read_pod<uint8>();
    SetBindPoseWhenMapping = buffer.read_pod<uint8>();
    BoneLengthAdjustmentType = buffer.read_pod<uint8>();
    PoweredConstraintParameters.read(buffer);
    RigidBodyControllerParameters.read(buffer);
    KeyframedRigidBodies.read(buffer);
    CollisionSubSystems.read(buffer);
}

