void ADFTypes::GameZoneSetup::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    LoopGain = buffer.read_pod<float32>();
    DetailModulation = buffer.read_pod<float32>();
    DetailCount = buffer.read_pod<int32>();
    for(int i = 0; i < 2; ++i) {
        DetailLength[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        DetailWait[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 2; ++i) {
        DetailGainRange[i] = buffer.read_pod<float32>();
    }
    SprinkleCount = buffer.read_pod<int32>();
    SprinkleRadius = buffer.read_pod<float32>();
    SprinkleSpacing = buffer.read_pod<float32>();
    for(int i = 0; i < 2; ++i) {
        SprinkleWait[i] = buffer.read_pod<float32>();
    }
    MixVolumeThreshold = buffer.read_pod<float32>();
    MixSpeed = buffer.read_pod<float32>();
}

