void ADFTypes::VegetationSystemInstance::read(IO::File& buffer) {
    X = buffer.read_pod<uint16>();
    Z = buffer.read_pod<uint16>();
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        Y = (bitfield_value >> 0) & ((1ULL << 24) - 1);
    }
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        ZoneIndex = (bitfield_value >> 0) & ((1ULL << 6) - 1);
        IsPlanted = (bitfield_value >> 6) & ((1ULL << 1) - 1);
        IsDestroyed = (bitfield_value >> 7) & ((1ULL << 1) - 1);
    }
    buffer.skip(3);
    Rotation = buffer.read_pod<uint32>();
    Color_R = buffer.read_pod<uint8>();
    Color_G = buffer.read_pod<uint8>();
    Color_B = buffer.read_pod<uint8>();
    buffer.skip(1);
    NameHash.read(buffer);
}

void ADFTypes::VegetationSystemInstance::print(std::ostream &out) const {
    out << "X: " << X << "\n";
    out << "Z: " << Z << "\n";
    out << "Y: " << Y << "\n";
    out << "ZoneIndex: " << ZoneIndex << "\n";
    out << "IsPlanted: " << IsPlanted << "\n";
    out << "IsDestroyed: " << IsDestroyed << "\n";
    out << "Rotation: " << Rotation << "\n";
    out << "Color_R: " << Color_R << "\n";
    out << "Color_G: " << Color_G << "\n";
    out << "Color_B: " << Color_B << "\n";
    out << "NameHash: ";
    NameHash.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::VegetationSystemInstance::to_json() const {
    nlohmann::json _res;
    _res["X"] = X;
    _res["Z"] = Z;
    _res["Y"] = Y;
    _res["ZoneIndex"] = ZoneIndex;
    _res["IsPlanted"] = IsPlanted;
    _res["IsDestroyed"] = IsDestroyed;
    _res["Rotation"] = Rotation;
    _res["Color_R"] = Color_R;
    _res["Color_G"] = Color_G;
    _res["Color_B"] = Color_B;
    _res["NameHash"] = NameHash.to_json();
    return _res;
}

