void ADFTypes::Value::read(IO::File& buffer) {
    NameHash.read(buffer);
    TypeHash.read(buffer);
    DataInt = buffer.read_pod<int32>();
    DataFloat = buffer.read_pod<float32>();
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        DataString = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    DataStringHash.read(buffer);
    for(int i = 0; i < 3; ++i) {
        DataVector3f[i] = buffer.read_pod<float32>();
    }
}

void ADFTypes::Value::print(std::ostream &out) const {
    out << "NameHash: ";
    NameHash.print(out);
    out << "\n";
    out << "TypeHash: ";
    TypeHash.print(out);
    out << "\n";
    out << "DataInt: " << DataInt << "\n";
    out << "DataFloat: " << DataFloat << "\n";
    out << "DataString: " << DataString << "\n";
    out << "DataStringHash: ";
    DataStringHash.print(out);
    out << "\n";
    out << "DataVector3f: \n";
    DataVector3f.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::Value::to_json() const {
    nlohmann::json _res;
    _res["NameHash"] = NameHash.to_json();
    _res["TypeHash"] = TypeHash.to_json();
    _res["DataInt"] = DataInt;
    _res["DataFloat"] = DataFloat;
    _res["DataString"] = DataString;
    _res["DataStringHash"] = DataStringHash.to_json();
    _res["DataVector3f"] = DataVector3f.to_json();
    return _res;
}

