void ADFTypes::HunterMission::read(IO::File& buffer) {
    Id = buffer.read_pod<int32>();
    Enabled = buffer.read_pod<uint8>();
    Required = buffer.read_pod<uint8>();
    Visible = buffer.read_pod<uint8>();
    buffer.skip(1);
    Type.read(buffer);
    Name.read(buffer);
    NameShort.read(buffer);
    AchievementId.read(buffer);
    ActivationEvent.read(buffer);
    CancelEvent.read(buffer);
    buffer.skip(4);
    SpecificCancelEvents.read(buffer);
    TimeLimit = buffer.read_pod<int32>();
    Summary.read(buffer);
    Description.read(buffer);
    Reward.read(buffer);
    buffer.skip(6);
    Locations.read(buffer);
    Regions.read(buffer);
    WarboardRegion = buffer.read_pod<uint64>();
    WarboardSubType.read(buffer);
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Banner = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    Character.read(buffer);
    ContentKey.read(buffer);
    DependenciesRequired.read(buffer);
    DependenciesOptional.read(buffer);
    ContentHash = buffer.read_pod<uint32>();
    CarryOver = buffer.read_pod<uint8>();
    CanCancelCompleted = buffer.read_pod<uint8>();
    CanSaveState = buffer.read_pod<uint8>();
    ShowInLog = buffer.read_pod<uint8>();
    Objectives.read(buffer);
    Events.read(buffer);
    Attachments.read(buffer);
    Randomizers.read(buffer);
    Variables.read(buffer);
}

