void ADFTypes::TextureBlend::read(IO::File& buffer) {
    EquipmentHash.read(buffer);
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Albedo = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Normal = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Mask = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Mpm = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::TextureBlend::print(std::ostream &out) const {
    out << "EquipmentHash: ";
    EquipmentHash.print(out);
    out << "\n";
    out << "Albedo: " << Albedo << "\n";
    out << "Normal: " << Normal << "\n";
    out << "Mask: " << Mask << "\n";
    out << "Mpm: " << Mpm << "\n";
}

nlohmann::json ADFTypes::TextureBlend::to_json() const {
    nlohmann::json _res;
    _res["EquipmentHash"] = EquipmentHash.to_json();
    _res["Albedo"] = Albedo;
    _res["Normal"] = Normal;
    _res["Mask"] = Mask;
    _res["Mpm"] = Mpm;
    return _res;
}

