void ADFTypes::AmfMesh::read(IO::File& buffer) {
    MeshTypeId.read(buffer);
    IndexCount = buffer.read_pod<uint32>();
    VertexCount = buffer.read_pod<uint32>();
    IndexBufferIndex = buffer.read_pod<uint8>();
    IndexBufferStride = buffer.read_pod<uint8>();
    buffer.skip(2);
    IndexBufferOffset = buffer.read_pod<uint32>();
    buffer.skip(4);
    VertexBufferIndices.read(buffer);
    VertexStreamStrides.read(buffer);
    VertexStreamOffsets.read(buffer);
    for(int i = 0; i < 3; ++i) {
        TextureDensities[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    MeshProperties = std::move(Deferred::read(buffer));
    BoneIndexLookup.read(buffer);
    SubMeshes.read(buffer);
    StreamAttributes.read(buffer);
}

void ADFTypes::AmfMesh::print(std::ostream &out) const {
    out << "MeshTypeId: ";
    MeshTypeId.print(out);
    out << "\n";
    out << "IndexCount: " << IndexCount << "\n";
    out << "VertexCount: " << VertexCount << "\n";
    out << "IndexBufferIndex: " << IndexBufferIndex << "\n";
    out << "IndexBufferStride: " << IndexBufferStride << "\n";
    out << "IndexBufferOffset: " << IndexBufferOffset << "\n";
    out << "VertexBufferIndices: \n";
    VertexBufferIndices.print(out);
    out << "\n";
    out << "VertexStreamStrides: \n";
    VertexStreamStrides.print(out);
    out << "\n";
    out << "VertexStreamOffsets: \n";
    VertexStreamOffsets.print(out);
    out << "\n";
    out << "TextureDensities: \n";
    TextureDensities.print(out);
    out << "\n";
    out << "MeshProperties: " << "\n";
    if (MeshProperties) {
        MeshProperties->print(out);
    }
    out << "BoneIndexLookup: \n";
    BoneIndexLookup.print(out);
    out << "\n";
    out << "SubMeshes: \n";
    SubMeshes.print(out);
    out << "\n";
    out << "StreamAttributes: \n";
    StreamAttributes.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::AmfMesh::to_json() const {
    nlohmann::json _res;
    _res["MeshTypeId"] = MeshTypeId.to_json();
    _res["IndexCount"] = IndexCount;
    _res["VertexCount"] = VertexCount;
    _res["IndexBufferIndex"] = IndexBufferIndex;
    _res["IndexBufferStride"] = IndexBufferStride;
    _res["IndexBufferOffset"] = IndexBufferOffset;
    _res["VertexBufferIndices"] = VertexBufferIndices.to_json();
    _res["VertexStreamStrides"] = VertexStreamStrides.to_json();
    _res["VertexStreamOffsets"] = VertexStreamOffsets.to_json();
    _res["TextureDensities"] = TextureDensities.to_json();
    if (MeshProperties) {
        _res["MeshProperties"] = MeshProperties->to_json();
    }
    _res["BoneIndexLookup"] = BoneIndexLookup.to_json();
    _res["SubMeshes"] = SubMeshes.to_json();
    _res["StreamAttributes"] = StreamAttributes.to_json();
    return _res;
}

