void ADFTypes::CarPaintMMConstants::read(IO::File& buffer) {
    Static.read(buffer);
    Dynamic.read(buffer);
    GIEmissionModulator = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        Decals = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        UseDamageBlend = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        Dirt = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        Tint = (bitfield_value >> 3) & ((1ULL << 1) - 1);
        TintSoftBlend = (bitfield_value >> 4) & ((1ULL << 1) - 1);
        Layered = (bitfield_value >> 5) & ((1ULL << 1) - 1);
        Overlay = (bitfield_value >> 6) & ((1ULL << 1) - 1);
        TwoSided = (bitfield_value >> 7) & ((1ULL << 1) - 1);
        AlphaBlend = (bitfield_value >> 8) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 9) & ((1ULL << 1) - 1);
        Rotating = (bitfield_value >> 10) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

void ADFTypes::CarPaintMMConstants::print(std::ostream &out) const {
    Static.print(out);
    Dynamic.print(out);
    out << "GIEmissionModulator: " << GIEmissionModulator << "\n";
    out << "Decals: " << Decals << "\n";
    out << "UseDamageBlend: " << UseDamageBlend << "\n";
    out << "Dirt: " << Dirt << "\n";
    out << "Tint: " << Tint << "\n";
    out << "TintSoftBlend: " << TintSoftBlend << "\n";
    out << "Layered: " << Layered << "\n";
    out << "Overlay: " << Overlay << "\n";
    out << "TwoSided: " << TwoSided << "\n";
    out << "AlphaBlend: " << AlphaBlend << "\n";
    out << "AlphaTest: " << AlphaTest << "\n";
    out << "Rotating: " << Rotating << "\n";
}

nlohmann::json ADFTypes::CarPaintMMConstants::to_json() const {
    nlohmann::json _res;
    _res["Static"] = Static.to_json();
    _res["Dynamic"] = Dynamic.to_json();
    _res["GIEmissionModulator"] = GIEmissionModulator;
    _res["Decals"] = Decals;
    _res["UseDamageBlend"] = UseDamageBlend;
    _res["Dirt"] = Dirt;
    _res["Tint"] = Tint;
    _res["TintSoftBlend"] = TintSoftBlend;
    _res["Layered"] = Layered;
    _res["Overlay"] = Overlay;
    _res["TwoSided"] = TwoSided;
    _res["AlphaBlend"] = AlphaBlend;
    _res["AlphaTest"] = AlphaTest;
    _res["Rotating"] = Rotating;
    return _res;
}

