void ADFTypes::RoadGraph::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        RoadType = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    RoadTypeHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    Nodes.read(buffer);
    Edges.read(buffer);
    NodeEdges.read(buffer);
    EdgeMap.read(buffer);
    EdgeSamples.read(buffer);
    EdgeRegions.read(buffer);
}

void ADFTypes::RoadGraph::print(std::ostream &out) const {
    out << "RoadType: " << RoadType << "\n";
    out << "RoadTypeHash: " << RoadTypeHash << "\n";
    out << "Nodes: \n";
    Nodes.print(out);
    out << "\n";
    out << "Edges: \n";
    Edges.print(out);
    out << "\n";
    out << "NodeEdges: \n";
    NodeEdges.print(out);
    out << "\n";
    out << "EdgeMap: \n";
    EdgeMap.print(out);
    out << "\n";
    EdgeSamples.print(out);
    out << "EdgeRegions: \n";
    EdgeRegions.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::RoadGraph::to_json() const {
    nlohmann::json _res;
    _res["RoadType"] = RoadType;
    _res["RoadTypeHash"] = RoadTypeHash;
    _res["Nodes"] = Nodes.to_json();
    _res["Edges"] = Edges.to_json();
    _res["NodeEdges"] = NodeEdges.to_json();
    _res["EdgeMap"] = EdgeMap.to_json();
    _res["EdgeSamples"] = EdgeSamples.to_json();
    _res["EdgeRegions"] = EdgeRegions.to_json();
    return _res;
}

