void ADFTypes::RoadInfoEx::read(IO::File& buffer) {
    SplinePoints.read(buffer);
    for(int i = 0; i < 3; ++i) {
        AABBMin[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        AABBMax[i] = buffer.read_pod<float32>();
    }
    GameObjectID = buffer.read_pod<uint64>();
    Length = buffer.read_pod<float32>();
    LaneCount = buffer.read_pod<uint8>();
    TraverseType = buffer.read_pod<uint8>();
    buffer.skip(2);
    LaneWidth = buffer.read_pod<float32>();
    DistBetweenVehicles = buffer.read_pod<uint16>();
    buffer.skip(2);
    SpeedLimit = buffer.read_pod<float32>();
    buffer.skip(4);
}

