void ADFTypes::VegetationSystemInstanceSrc::read(IO::File& buffer) {
    X = buffer.read_pod<float32>();
    Y = buffer.read_pod<float32>();
    Z = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        Rotation[i] = buffer.read_pod<float32>();
    }
    Color_R = buffer.read_pod<float32>();
    Color_G = buffer.read_pod<float32>();
    Color_B = buffer.read_pod<float32>();
    NameHash.read(buffer);
    ZoneIndex = buffer.read_pod<uint8>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        IsPlanted = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

void ADFTypes::VegetationSystemInstanceSrc::print(std::ostream &out) const {
    out << "X: " << X << "\n";
    out << "Y: " << Y << "\n";
    out << "Z: " << Z << "\n";
    out << "Rotation: \n";
    Rotation.print(out);
    out << "\n";
    out << "Color_R: " << Color_R << "\n";
    out << "Color_G: " << Color_G << "\n";
    out << "Color_B: " << Color_B << "\n";
    out << "NameHash: ";
    NameHash.print(out);
    out << "\n";
    out << "ZoneIndex: " << ZoneIndex << "\n";
    out << "IsPlanted: " << IsPlanted << "\n";
}

nlohmann::json ADFTypes::VegetationSystemInstanceSrc::to_json() const {
    nlohmann::json _res;
    _res["X"] = X;
    _res["Y"] = Y;
    _res["Z"] = Z;
    _res["Rotation"] = Rotation.to_json();
    _res["Color_R"] = Color_R;
    _res["Color_G"] = Color_G;
    _res["Color_B"] = Color_B;
    _res["NameHash"] = NameHash.to_json();
    _res["ZoneIndex"] = ZoneIndex;
    _res["IsPlanted"] = IsPlanted;
    return _res;
}

static std::unique_ptr<ADFTypes::VegetationSystemInstanceSrc> VegetationSystemInstanceSrc_new_instance() {
    return std::make_unique<ADFTypes::VegetationSystemInstanceSrc>();
}

