    vulnerable_duration_s = buffer.read_pod<uint16>();
    explosion_threshold = buffer.read_pod<int32>();
    npc_explosion_threshold = buffer.read_pod<int32>();
    vulnerable_explosion_threshold = buffer.read_pod<int32>();
    impact_deform_threshold = buffer.read_pod<int32>();
