void ADFTypes::WorldSaveData12::read(IO::File& buffer) {
    Regions.read(buffer);
    AnimalPopulations.read(buffer);
    Collectables.read(buffer);
    LootSeed = buffer.read_pod<uint32>();
    buffer.skip(4);
    FogOfWar.read(buffer);
    ReserveId = buffer.read_pod<int32>();
    buffer.skip(4);
    Locations.read(buffer);
    CodexInfos.read(buffer);
    PlayerFoundIcons.read(buffer);
    Statistics.read(buffer);
    ContextualHelpInfos.read(buffer);
    ContextualHelpActive = buffer.read_pod<uint8>();
    buffer.skip(7);
    LocationSummaries.read(buffer);
    Raids.read(buffer);
    Timers.read(buffer);
    PlayerSpawnPoints.read(buffer);
    RivalRegions.read(buffer);
    for(int i = 0; i < 2; ++i) {
        RivalUsedNumbers[i] = buffer.read_pod<uint64>();
    }
    DifficultyLevel = buffer.read_pod<uint32>();
    DifficultyScaleByPlayers = buffer.read_pod<uint8>();
    buffer.skip(3);
    ControlPoints.read(buffer);
    RivalMissionGroups.read(buffer);
}

