void ADFTypes::SchematicTreeNode::read(IO::File& buffer) {
    EquipmentHash = buffer.read_pod<uint32>();
    Currency = buffer.read_pod<uint32>();
    UnlockCost = buffer.read_pod<int32>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        ConsumeCost = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(1);
    for(int i = 0; i < 8; ++i) {
        Prerequisites[i] = buffer.read_pod<uint16>();
    }
    for(int i = 0; i < 8; ++i) {
        Children[i] = buffer.read_pod<uint16>();
    }
    DisplayMode = buffer.read_pod<uint8>();
    buffer.skip(1);
}

void ADFTypes::SchematicTreeNode::print(std::ostream &out) const {
    out << "EquipmentHash: " << EquipmentHash << "\n";
    out << "Currency: " << Currency << "\n";
    out << "UnlockCost: " << UnlockCost << "\n";
    out << "ConsumeCost: " << ConsumeCost << "\n";
    out << "Prerequisites: \n";
    Prerequisites.print(out);
    out << "\n";
    out << "Children: \n";
    Children.print(out);
    out << "\n";
    out << "DisplayMode: " << DisplayMode << "\n";
}

nlohmann::json ADFTypes::SchematicTreeNode::to_json() const {
    nlohmann::json _res;
    _res["EquipmentHash"] = EquipmentHash;
    _res["Currency"] = Currency;
    _res["UnlockCost"] = UnlockCost;
    _res["ConsumeCost"] = ConsumeCost;
    _res["Prerequisites"] = Prerequisites.to_json();
    _res["Children"] = Children.to_json();
    _res["DisplayMode"] = DisplayMode;
    return _res;
}

static std::unique_ptr<ADFTypes::SchematicTreeNode> SchematicTreeNode_new_instance() {
    return std::make_unique<ADFTypes::SchematicTreeNode>();
}

