void ADFTypes::ProfileSaveData3::read(IO::File& buffer) {
    Collectables.read(buffer);
    EmotesUnlocked.read(buffer);
    for(int i = 0; i < 8; ++i) {
        EmoteSlots[i] = buffer.read_pod<uint32>();
    }
    TrackingId = buffer.read_pod<uint64>();
    Settings.read(buffer);
    CompletedBounties.read(buffer);
    LastLogin = buffer.read_pod<int64>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        SocialDisabled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    VehiclePreferedCameraThirdPerson = buffer.read_pod<uint8>();
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        TrackingEnabled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        ShownTrackingOptIn = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        CrashReportingEnabled = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        ShownCrashReportingEnabledOptIn = (bitfield_value >> 3) & ((1ULL << 1) - 1);
    }
    buffer.skip(5);
    ResourceStorage.read(buffer);
    SafehouseStorage.read(buffer);
    SafehouseStorageSizeColumns = buffer.read_pod<uint8>();
    SafehouseStorageSizeRows = buffer.read_pod<uint8>();
    buffer.skip(6);
}

void ADFTypes::ProfileSaveData3::print(std::ostream &out) const {
    out << "Collectables: \n";
    Collectables.print(out);
    out << "\n";
    out << "EmotesUnlocked: \n";
    EmotesUnlocked.print(out);
    out << "\n";
    out << "EmoteSlots: \n";
    EmoteSlots.print(out);
    out << "\n";
    out << "TrackingId: " << TrackingId << "\n";
    out << "Settings: \n";
    Settings.print(out);
    out << "\n";
    out << "CompletedBounties: \n";
    CompletedBounties.print(out);
    out << "\n";
    out << "LastLogin: " << LastLogin << "\n";
    out << "SocialDisabled: " << SocialDisabled << "\n";
    out << "VehiclePreferedCameraThirdPerson: " << VehiclePreferedCameraThirdPerson << "\n";
    out << "TrackingEnabled: " << TrackingEnabled << "\n";
    out << "ShownTrackingOptIn: " << ShownTrackingOptIn << "\n";
    out << "CrashReportingEnabled: " << CrashReportingEnabled << "\n";
    out << "ShownCrashReportingEnabledOptIn: " << ShownCrashReportingEnabledOptIn << "\n";
    out << "ResourceStorage: \n";
    ResourceStorage.print(out);
    out << "\n";
    out << "SafehouseStorage: \n";
    SafehouseStorage.print(out);
    out << "\n";
    out << "SafehouseStorageSizeColumns: " << SafehouseStorageSizeColumns << "\n";
    out << "SafehouseStorageSizeRows: " << SafehouseStorageSizeRows << "\n";
}

nlohmann::json ADFTypes::ProfileSaveData3::to_json() const {
    nlohmann::json _res;
    _res["Collectables"] = Collectables.to_json();
    _res["EmotesUnlocked"] = EmotesUnlocked.to_json();
    _res["EmoteSlots"] = EmoteSlots.to_json();
    _res["TrackingId"] = TrackingId;
    _res["Settings"] = Settings.to_json();
    _res["CompletedBounties"] = CompletedBounties.to_json();
    _res["LastLogin"] = LastLogin;
    _res["SocialDisabled"] = SocialDisabled;
    _res["VehiclePreferedCameraThirdPerson"] = VehiclePreferedCameraThirdPerson;
    _res["TrackingEnabled"] = TrackingEnabled;
    _res["ShownTrackingOptIn"] = ShownTrackingOptIn;
    _res["CrashReportingEnabled"] = CrashReportingEnabled;
    _res["ShownCrashReportingEnabledOptIn"] = ShownCrashReportingEnabledOptIn;
    _res["ResourceStorage"] = ResourceStorage.to_json();
    _res["SafehouseStorage"] = SafehouseStorage.to_json();
    _res["SafehouseStorageSizeColumns"] = SafehouseStorageSizeColumns;
    _res["SafehouseStorageSizeRows"] = SafehouseStorageSizeRows;
    return _res;
}

