void ADFTypes::Shader::read(IO::File& buffer) {
    NameHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    DataHash = buffer.read_pod<uint32>();
    buffer.skip(4);
    BinaryData.read(buffer);
}

void ADFTypes::Shader::print(std::ostream &out) const {
    out << "NameHash: " << NameHash << "\n";
    out << "Name: " << Name << "\n";
    out << "DataHash: " << DataHash << "\n";
    out << "BinaryData: \n";
    BinaryData.print(out);
    out << "\n";
}

nlohmann::json ADFTypes::Shader::to_json() const {
    nlohmann::json _res;
    _res["NameHash"] = NameHash;
    _res["Name"] = Name;
    _res["DataHash"] = DataHash;
    _res["BinaryData"] = BinaryData.to_json();
    return _res;
}

