void ADFTypes::HairConstants::read(IO::File& buffer) {
    SpecularGloss = buffer.read_pod<float32>();
    TransmissionIntensity = buffer.read_pod<float32>();
    SpecularFresnel = buffer.read_pod<float32>();
    DiffuseWrap = buffer.read_pod<float32>();
    DiffuseRoughness = buffer.read_pod<float32>();
    AnisotropicStrength = buffer.read_pod<float32>();
    AnisotropicX = buffer.read_pod<float32>();
    AnisotropicY = buffer.read_pod<float32>();
    RimStrength = buffer.read_pod<float32>();
    RingStrength = buffer.read_pod<float32>();
    RingAngle = buffer.read_pod<float32>();
    RingOffset = buffer.read_pod<float32>();
    {
        const uint16 bitfield_value = buffer.read_pod<uint16>();
        DoubleSided = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        AlphaTest = (bitfield_value >> 1) & ((1ULL << 1) - 1);
        AlphaBlending = (bitfield_value >> 2) & ((1ULL << 1) - 1);
        UseColorMask = (bitfield_value >> 3) & ((1ULL << 1) - 1);
    }
    buffer.skip(2);
}

