void ADFTypes::AnimalSaveData2::read(IO::File& buffer) {
    PopulationNameHashId = buffer.read_pod<uint32>();
    GroupIndex = buffer.read_pod<uint32>();
    Loadout = buffer.read_pod<uint8>();
    buffer.skip(3);
    VisualVariationSeed = buffer.read_pod<uint32>();
    for(int i = 0; i < 64; ++i) {
        Parts[i].read(buffer);
    }
    PartsCount = buffer.read_pod<uint8>();
    for(int i = 0; i < 64; ++i) {
        DynamicMaterialWeights[i] = buffer.read_pod<uint8>();
    }
    buffer.skip(7);
    PersistentStats.read(buffer);
    RivalId = buffer.read_pod<uint32>();
    buffer.skip(4);
}

void ADFTypes::AnimalSaveData2::print(std::ostream &out) const {
    out << "PopulationNameHashId: " << PopulationNameHashId << "\n";
    out << "GroupIndex: " << GroupIndex << "\n";
    out << "Loadout: " << Loadout << "\n";
    out << "VisualVariationSeed: " << VisualVariationSeed << "\n";
    out << "Parts: \n";
    Parts.print(out);
    out << "\n";
    out << "PartsCount: " << PartsCount << "\n";
    out << "DynamicMaterialWeights: \n";
    DynamicMaterialWeights.print(out);
    out << "\n";
    PersistentStats.print(out);
    out << "RivalId: " << RivalId << "\n";
}

nlohmann::json ADFTypes::AnimalSaveData2::to_json() const {
    nlohmann::json _res;
    _res["PopulationNameHashId"] = PopulationNameHashId;
    _res["GroupIndex"] = GroupIndex;
    _res["Loadout"] = Loadout;
    _res["VisualVariationSeed"] = VisualVariationSeed;
    _res["Parts"] = Parts.to_json();
    _res["PartsCount"] = PartsCount;
    _res["DynamicMaterialWeights"] = DynamicMaterialWeights.to_json();
    _res["PersistentStats"] = PersistentStats.to_json();
    _res["RivalId"] = RivalId;
    return _res;
}

