void ADFTypes::VegetationWorld::read(IO::File& buffer) {
    VegetationLayers.read(buffer);
    VegetationZones.read(buffer);
    VegetationObjects.read(buffer);
    DefaultVegetationZone.read(buffer);
    VegetationIndex.read(buffer);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        BillboardAtlasDiffuse = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        BillboardAtlasNormal = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    for(int i = 0; i < 3; ++i) {
        WorldSize[i] = buffer.read_pod<float32>();
    }
    buffer.skip(4);
    ImpostorCollection.read(buffer);
}

void ADFTypes::VegetationWorld::print(std::ostream &out) const {
    VegetationLayers.print(out);
    out << "VegetationZones: \n";
    VegetationZones.print(out);
    out << "\n";
    out << "VegetationObjects: \n";
    VegetationObjects.print(out);
    out << "\n";
    DefaultVegetationZone.print(out);
    out << "VegetationIndex: \n";
    VegetationIndex.print(out);
    out << "\n";
    out << "BillboardAtlasDiffuse: " << BillboardAtlasDiffuse << "\n";
    out << "BillboardAtlasNormal: " << BillboardAtlasNormal << "\n";
    out << "WorldSize: \n";
    WorldSize.print(out);
    out << "\n";
    ImpostorCollection.print(out);
}

nlohmann::json ADFTypes::VegetationWorld::to_json() const {
    nlohmann::json _res;
    _res["VegetationLayers"] = VegetationLayers.to_json();
    _res["VegetationZones"] = VegetationZones.to_json();
    _res["VegetationObjects"] = VegetationObjects.to_json();
    _res["DefaultVegetationZone"] = DefaultVegetationZone.to_json();
    _res["VegetationIndex"] = VegetationIndex.to_json();
    _res["BillboardAtlasDiffuse"] = BillboardAtlasDiffuse;
    _res["BillboardAtlasNormal"] = BillboardAtlasNormal;
    _res["WorldSize"] = WorldSize.to_json();
    _res["ImpostorCollection"] = ImpostorCollection.to_json();
    return _res;
}

