void ADFTypes::TerrainMaterial::read(IO::File& buffer) {
    NameHash.read(buffer);
    VegetationSet.read(buffer);
    GameMaterial.read(buffer);
    TextureNearIndex = buffer.read_pod<uint8>();
    TextureMidIndex = buffer.read_pod<uint8>();
    buffer.skip(2);
    Transmissive = buffer.read_pod<float32>();
    ColorInfluence = buffer.read_pod<float32>();
    for(int i = 0; i < 3; ++i) {
        ColorNear[i] = buffer.read_pod<uint8>();
    }
    for(int i = 0; i < 3; ++i) {
        ColorMid[i] = buffer.read_pod<uint8>();
    }
    {
        const uint8 bitfield_value = buffer.read_pod<uint8>();
        GroundHaze = (bitfield_value >> 0) & ((1ULL << 1) - 1);
    }
    buffer.skip(1);
    NormalDampening = buffer.read_pod<float32>();
    DisplacementScale = buffer.read_pod<float32>();
    DisplacementBias = buffer.read_pod<float32>();
    DisplacementMip = buffer.read_pod<uint8>();
    buffer.skip(3);
    BlendScale = buffer.read_pod<float32>();
    BlendBias = buffer.read_pod<float32>();
}

