void ADFTypes::ExtendedEffectUsage::read(IO::File& buffer) {
    name.read(buffer);
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        activation_expression = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        deactivation_expression = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
}

void ADFTypes::ExtendedEffectUsage::print(std::ostream &out) const {
    name.print(out);
    out << "activation_expression: " << activation_expression << "\n";
    out << "deactivation_expression: " << deactivation_expression << "\n";
}

nlohmann::json ADFTypes::ExtendedEffectUsage::to_json() const {
    nlohmann::json _res;
    _res["name"] = name.to_json();
    _res["activation_expression"] = activation_expression;
    _res["deactivation_expression"] = deactivation_expression;
    return _res;
}

