void ADFTypes::WorldSaveData27::read(IO::File& buffer) {
    ReserveId = buffer.read_pod<int32>();
    buffer.skip(4);
    Statistics.read(buffer);
    DifficultyLevel = buffer.read_pod<uint32>();
    DifficultyScaleByPlayers = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 4; ++i) {
        Worlds[i].read(buffer);
    }
    ActiveWorldIndex = buffer.read_pod<uint32>();
    buffer.skip(4);
}

