void ADFTypes::ShaderLibrary::read(IO::File& buffer) {
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        Name = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    {
        std::streamoff original_offset = buffer.get_position();
        uint32 string_offset = buffer.read_pod<uint32>();
        uint32 unk = buffer.read_pod<uint32>();
        buffer.set_position(string_offset, std::ios::beg);
        BuildTime = buffer.read_cstring();
        buffer.set_position(original_offset, std::ios::beg);
    }
    VertexShaders.read(buffer);
    FragmentShaders.read(buffer);
    ComputeShaders.read(buffer);
    GeometryShaders.read(buffer);
    HullShaders.read(buffer);
    DomainShaders.read(buffer);
}

void ADFTypes::ShaderLibrary::print(std::ostream &out) const {
    out << "Name: " << Name << "\n";
    out << "BuildTime: " << BuildTime << "\n";
    out << "VertexShaders: \n";
    VertexShaders.print(out);
    out << "\n";
    out << "FragmentShaders: \n";
    FragmentShaders.print(out);
    out << "\n";
    out << "ComputeShaders: \n";
    ComputeShaders.print(out);
    out << "\n";
    out << "GeometryShaders: \n";
    GeometryShaders.print(out);
    out << "\n";
    out << "HullShaders: \n";
    HullShaders.print(out);
    out << "\n";
    out << "DomainShaders: \n";
    DomainShaders.print(out);
    out << "\n";
}

