void ADFTypes::LightInfo::read(IO::File& buffer) {
    for(int i = 0; i < 3; ++i) {
        Position[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        Diffuse[i] = buffer.read_pod<uint8>();
    }
    Radius = buffer.read_pod<uint8>();
    HasDistantLod = buffer.read_pod<uint8>();
    buffer.skip(7);
    ObjectID = buffer.read_pod<uint64>();
    Ordinal = buffer.read_pod<uint32>();
    CellIndex = buffer.read_pod<uint16>();
    buffer.skip(2);
}

