void ADFTypes::TerrainTexture::read(IO::File& buffer) {
    Width = buffer.read_pod<uint32>();
    Height = buffer.read_pod<uint32>();
    BlockCompressionType = static_cast<ADFTypes::BlockCompressionType>(buffer.read_pod<uint32>());
    {
        const uint32 bitfield_value = buffer.read_pod<uint32>();
        Tiled = (bitfield_value >> 0) & ((1ULL << 1) - 1);
        Srgb = (bitfield_value >> 1) & ((1ULL << 1) - 1);
    }
    Data.read(buffer);
}

void ADFTypes::TerrainTexture::print(std::ostream &out) const {
    out << "Width: " << Width << "\n";
    out << "Height: " << Height << "\n";
    out << "BlockCompressionType: " << BlockCompressionType << "\n";
    out << "Tiled: " << Tiled << "\n";
    out << "Srgb: " << Srgb << "\n";
    Data.print(out);
}

nlohmann::json ADFTypes::TerrainTexture::to_json() const {
    nlohmann::json _res;
    _res["Width"] = Width;
    _res["Height"] = Height;
    _res["BlockCompressionType"] = BlockCompressionType;
    _res["Tiled"] = Tiled;
    _res["Srgb"] = Srgb;
    _res["Data"] = Data.to_json();
    return _res;
}

