void ADFTypes::ShaderRules::read(IO::File& buffer) {
    NameHash.read(buffer);
    AudioZone.read(buffer);
    TopographyIndex = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 2; ++i) {
        Rotation[i] = buffer.read_pod<float32>();
    }
    RotationIndex = buffer.read_pod<uint8>();
    buffer.skip(3);
    for(int i = 0; i < 4; ++i) {
        VariationMaterials[i].read(buffer);
    }
    VariationIndex = buffer.read_pod<uint8>();
    InvertVariation = buffer.read_pod<uint8>();
    TransitionSlot = buffer.read_pod<uint8>();
    buffer.skip(1);
    SlotBlendFactor = buffer.read_pod<float32>();
    NormalDetailBalance = buffer.read_pod<float32>();
    for(int i = 0; i < 4; ++i) {
        PrimitiveMaterials[i].read(buffer);
    }
    for(int i = 0; i < 4; ++i) {
        VariationSlotCenters[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 4; ++i) {
        NormalSlotCenters[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 4; ++i) {
        PrimitiveSlotCenters[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        ColorNear[i] = buffer.read_pod<uint8>();
    }
    for(int i = 0; i < 3; ++i) {
        ColorMid[i] = buffer.read_pod<uint8>();
    }
    for(int i = 0; i < 3; ++i) {
        DebugColor[i] = buffer.read_pod<uint8>();
    }
    ProjectionType = buffer.read_pod<uint8>();
    buffer.skip(2);
    DisplacementScale = buffer.read_pod<float32>();
    DisplacementBias = buffer.read_pod<float32>();
    DisplacementMip = buffer.read_pod<uint8>();
    buffer.skip(3);
    BlendScale = buffer.read_pod<float32>();
    BlendBias = buffer.read_pod<float32>();
}

