void ADFTypes::ImpostorMesh::read(IO::File& buffer) {
    Indices.read(buffer);
    Vertices.read(buffer);
    for(int i = 0; i < 2; ++i) {
        Size[i] = buffer.read_pod<float32>();
    }
    for(int i = 0; i < 3; ++i) {
        Offset[i] = buffer.read_pod<float32>();
    }
    Single = buffer.read_pod<uint8>();
    buffer.skip(3);
}

